    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == 5:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue

                # Find the ends of this contiguous diagonal run.
                sr, sc = r, c
                while (0 <= sr-dr < h and 0 <= sc-dc < w
                       and grid[sr-dr][sc-dc] == color):
                    sr, sc = sr-dr, sc-dc
                er, ec = r, c
                while (0 <= er+dr < h and 0 <= ec+dc < w
                       and grid[er+dr][ec+dc] == color):
                    er, ec = er+dr, ec+dc
                key = (sr, sc, er, ec, color)
                if key in seen:
                    continue
                seen.add(key)

                # Prefer continuing in the direction of the observed diagonal;
                # if blocked, extend from its opposite end instead.
                for rr, cc, step_r, step_c in (
                    (er+dr, ec+dc, dr, dc),
                    (sr-dr, sc-dc, -dr, -dc),
                ):
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                            out[rr][cc] = color
                            rr += step_r
                            cc += step_c
                        break
    return out
